// Runs as the server's build step on Vercel: packs the Vanity desktop app (the repo
// root) into an update bundle that the server hands out at /update and /update/download.
// Usage: node scripts/build-update-bundle.mjs [--out <file>]
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, relative, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import { zip } from './zip.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..', '..')
const outArg = process.argv.indexOf('--out')
const out = outArg > 0 ? process.argv[outArg + 1] : join(here, '..', 'src', 'generated', 'update-bundle.ts')

/** Never shipped: dependencies, builds, git data, secrets, and the bundle itself. */
const SKIP_DIRS = new Set(['node_modules', '.git', 'out', 'dist', '.vercel', 'data'])
const SKIP_PATHS = new Set(['server/src/generated'])
const skipFile = (name) => /^\.env(\..*)?$/.test(name) && name !== '.env.example' || name.endsWith('.tsbuildinfo') || name === '.DS_Store'

function walk(dir, files) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, e.name)
    const rel = relative(root, full).split(sep).join('/')
    if (e.isDirectory()) {
      if (!SKIP_DIRS.has(e.name) && !SKIP_PATHS.has(rel)) walk(full, files)
    } else if (e.isFile() && !skipFile(e.name)) files.push({ name: rel, data: readFileSync(full) })
  }
  return files
}

let pkg
try {
  pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
} catch {
  // Don't fail the deploy: the server still works, it just has no updates to hand out.
  console.warn(`[update-bundle] No Vanity app found at ${root}, so this deployment won't serve updates. On Vercel, keep "Include files outside the root directory" on.`)
  writeFileSync(out, `// Generated by scripts/build-update-bundle.mjs: no app was found at build time.\nimport type { UpdateBundle } from '../updates'\n\nexport const updateBundle: UpdateBundle | null = null\n`)
  process.exit(0)
}
const files = walk(root, []).sort((a, b) => a.name.localeCompare(b.name))
const data = zip(files)
let changelog = ''
try {
  changelog = readFileSync(join(root, 'CHANGELOG.md'), 'utf8')
} catch {
  // No changelog: the app shows a generic note.
}
const bundle = {
  version: pkg.version,
  changelog,
  sha: process.env.VERCEL_GIT_COMMIT_SHA ?? null,
  builtAt: Date.now(),
  size: data.length,
  zipBase64: data.toString('base64')
}
writeFileSync(
  out,
  `// Generated by scripts/build-update-bundle.mjs at build time. Do not edit or commit a generated version.\nimport type { UpdateBundle } from '../updates'\n\nexport const updateBundle: UpdateBundle | null = ${JSON.stringify(bundle)}\n`
)
console.log(`[update-bundle] Vanity ${pkg.version}: ${files.length} files, ${(data.length / 1024).toFixed(0)} KB`)
